# The validator is confused by self-closing tags and void elements. Let's do a proper check.
from html.parser import HTMLParser

class SimpleChecker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.void = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
        self.errors = []
        self.img_count = 0

    def handle_starttag(self, tag, attrs):
        if tag not in self.void:
            self.stack.append(tag)
        if tag == 'img':
            self.img_count += 1

    def handle_endtag(self, tag):
        if tag in self.void:
            return
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        else:
            # Try to find it deeper
            if tag in self.stack:
                while self.stack and self.stack[-1] != tag:
                    self.stack.pop()
                if self.stack:
                    self.stack.pop()
            else:
                self.errors.append(f"Closing unopened tag: {tag}")

